let audienceImportRows=[];
function downloadAudienceTemplate(){
 const csv='nombre,poblacion,impacto,barreras\r\nLíderes,35,Alto,Disponibilidad\r\nOperaciones,120,Medio,Capacitación';
 const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='HACERLO_plantilla_audiencias.csv';a.click();URL.revokeObjectURL(url);
}
function parseAudienceCSV(text){
 text=text.replace(/^\uFEFF/,'');let rows=[],row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}
 else if(c===','&&!quoted){row.push(cell.trim());cell=''}
 else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c}
 if(quoted)throw Error('Hay comillas sin cerrar en el archivo');row.push(cell.trim());if(row.some(x=>x!==''))rows.push(row);
 return rows;
}
async function previewAudienceCSV(input){
 const target=document.getElementById('audience-import-preview');audienceImportRows=[];
 if(!input.files.length)return;
 try{
 const file=input.files[0];if(file.size>2e6)throw Error('El archivo supera 2 MB');
 const lines=parseAudienceCSV(await file.text());if(lines.length<2)throw Error('No hay filas para importar');
 const headers=lines.shift().map(x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim());
 if(!['nombre','poblacion','impacto','barreras'].every(h=>headers.includes(h)))throw Error('Encabezados requeridos: nombre,poblacion,impacto,barreras');
 if(lines.length>2000)throw Error('Máximo 2.000 audiencias por archivo');
 const existing=new Set(current().audiences.map(a=>a.name.trim().toLocaleLowerCase('es'))),seen=new Set();
 audienceImportRows=lines.map((line,index)=>{
 let obj=Object.fromEntries(headers.map((h,i)=>[h,(line[i]||'').trim()]));
 let key=obj.nombre.toLocaleLowerCase('es'),pop=obj.poblacion;
 let errors=[];if(!obj.nombre)errors.push('Nombre vacío');if(pop&&!/^[0-9]+$/.test(pop))errors.push('Población inválida');
 if(obj.impacto&&!['Alto','Medio','Bajo'].includes(obj.impacto))errors.push('Impacto debe ser Alto, Medio o Bajo');
 if(seen.has(key))errors.push('Duplicada dentro del archivo');seen.add(key);
 return {row:index+2,name:obj.nombre,population:pop,impact:obj.impacto,barriers:obj.barreras,existing:existing.has(key),errors};
 });
 let valid=audienceImportRows.filter(r=>!r.errors.length);
 target.innerHTML=`<p>${valid.length} registros válidos; ${audienceImportRows.length-valid.length} con errores; ${valid.filter(r=>r.existing).length} existentes.</p>`+
 `<div style="max-height:270px;overflow:auto"><table><tr><th>Fila</th><th>Audiencia</th><th>Población</th><th>Impacto</th><th>Resultado</th></tr>`+
 audienceImportRows.map(r=>`<tr><td>${r.row}</td><td>${safe(r.name)}</td><td>${safe(r.population)}</td><td>${safe(r.impact)}</td><td>${r.errors.length?safe(r.errors.join('; ')):r.existing?'Existente':'Nueva'}</td></tr>`).join('')+'</table></div>'+
 `<label>Registros existentes<select id="audience-duplicate-mode"><option value="skip">Omitir (conservar datos actuales)</option><option value="update">Actualizar con valores importados</option></select></label>`+
 `<button type="button" class="primary" ${valid.length?'':'disabled'} onclick="commitAudienceImport()">Importar ${valid.length} registros válidos</button>`;
 }catch(e){target.textContent='Error: '+e.message}
}
function commitAudienceImport(){
 let x=current(),mode=document.getElementById('audience-duplicate-mode').value,added=0,updated=0,skipped=0;
 for(let r of audienceImportRows.filter(r=>!r.errors.length)){
 let old=x.audiences.find(a=>a.name.trim().toLocaleLowerCase('es')===r.name.trim().toLocaleLowerCase('es'));
 if(old&&mode==='skip'){skipped++;continue}
 if(old){Object.assign(old,{population:r.population,impact:r.impact,barriers:r.barriers});updated++}
 else{x.audiences.push({id:'aud-'+Date.now()+'-'+added+'-'+Math.random().toString(36).slice(2,7),name:r.name,population:r.population,impact:r.impact,barriers:r.barriers});added++}
 }
 save();alert(`Importación terminada: ${added} nuevas, ${updated} actualizadas, ${skipped} omitidas. Las filas con errores no se importaron.`);audienceImportRows=[];render();
}

function audienceChecks(x){return x.audiences.length?x.audiences.map(a=>`<label style="display:block"><input style="width:auto" type="checkbox" name="audienceIds" value="${a.id}"> ${safe(a.name)}</label>`).join(''):'<p class="muted">Crea una audiencia antes de seleccionar.</p>'}
function audienceForm(){return `<div class="panel"><h3>Nueva audiencia</h3><div class="audience-fields"><input data-field="name" placeholder="Nombre de la audiencia"><input data-field="population" type="number" min="0" placeholder="Número de personas"><select data-field="impact"><option value="">Impacto sin evaluar</option><option>Alto</option><option>Medio</option><option>Bajo</option></select><textarea data-field="barriers" placeholder="Barreras y facilitadores (opcional)"></textarea><button type="button" class="primary" onclick="addAudienceFromButton(this)">Guardar audiencia</button></div></div>`}
function audienceList(x){return x.audiences.length?x.audiences.map(a=>`<div class="panel"><strong>${safe(a.name)}</strong><p class="muted">${safe(a.population||'—')} personas · Impacto: ${safe(a.impact||'Sin evaluar')}</p></div>`).join(''):'<div class="empty">No hay audiencias registradas.</div>'}
function behaviorAudienceLabel(x,b){return b.scope!=='specific'?'Todas las audiencias':(b.audienceIds||[]).map(id=>x.audiences.find(a=>a.id===id)?.name||'Audiencia eliminada').map(safe).join(', ')||'Sin audiencia seleccionada'}
function showAudienceForm(id){$(id).classList.toggle('hide')}
function addAudienceFromButton(button){
 const fields=button.closest('.audience-fields');
 if(!fields)return;
 const a=Object.fromEntries([...fields.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value]));
 if(!String(a.name||'').trim())return alert('Indica el nombre de la audiencia');
 a.id='aud-'+Date.now();
 current().audiences.push(a);
 save();
 // Al crear una audiencia desde Diseño, conservar el comportamiento que ya se está redactando.
 const design=button.closest('#behavior-design-creator');
 const target=design?.querySelector('.behavior-create-audience-list');
 if(target){
  const placeholder=target.querySelector('p.muted');
  if(placeholder)placeholder.remove();
  const label=document.createElement('label'),checkbox=document.createElement('input'),text=document.createElement('span');
  label.style.display='flex';label.style.alignItems='center';label.style.gap='8px';
  checkbox.type='checkbox';checkbox.name='audienceIds';checkbox.value=a.id;checkbox.style.width='auto';
  checkbox.checked=design.querySelector('[name="scope"]')?.value==='specific';
  text.textContent=a.name;label.append(checkbox,text);target.append(label);
  button.closest('#designAudience')?.classList.add('hide');
  return;
 }
 render();
}

// HACERLO V2.2: clasificación configurable, con reglas explícitas (no inferencias sobre personas).
const AUD_AUTH={'Decisor':10,'Influenciador Directo':9,'Influenciador Indirecto':8,'Espectador':5};
const AUD_POSITION={'Promotor':10,'Pasivo':8,'Probable Resistente':6,'Saboteador Abierto':5,'Saboteador Oculto':4};
const AUD_STRATEGIES={Q1:['Cocrear decisiones clave','Patrocinio visible','Involucrar en diseño y validación'],Q2:['Consultas ejecutivas puntuales','Validación de decisiones clave','Negociación y manejo de expectativas'],Q3:['Comunicaciones generales','Actualizaciones periódicas','Monitorear cambios de interés'],Q4:['Escucha activa','Talleres, pilotos y grupos focales','Espacios de retroalimentación']};
let audienceTab='registro',audienceEditing=null,audienceFilter='',audienceSelected=null,audienceQuadrantFilter='';
let audQuickCreateOpen=false;
function audQuickNew(){audienceTab='registro';audienceEditing=null;audQuickCreateOpen=true;render();
 document.querySelector('.aud-setup details')?.scrollIntoView({behavior:'smooth',block:'start'});}
function audScore(a){return {authority:AUD_AUTH[a.authority]??null,interest:AUD_POSITION[a.position]??null}}
function audQuadrant(a){let s=audScore(a);if(s.authority===null||s.interest===null)return null;return `Q${s.authority>=7?(s.interest>=7?1:2):(s.interest>=7?4:3)}`}
function audSelect(field,values,value){return `<select name="${field}"><option value="">Sin clasificar</option>${Object.keys(values).map(k=>`<option ${value===k?'selected':''}>${safe(k)}</option>`).join('')}</select>`}
function audInput(label,field,value='',type='text'){return `<label>${label}<input type="${type}" name="${field}" value="${safe(value)}"></label>`}
function audienceManagementPage(x){audInitPeopleUI(x);if(typeof graphSyncAudiences==='function'&&graphSyncAudiences(x))save();let rows=x.audiences||[],counts={Q1:0,Q2:0,Q3:0,Q4:0};rows.forEach(a=>{let q=audQuadrant(a);if(q)counts[q]+=a.kind==='Grupo'?Number(a.population)||0:1});return hcxHero('Gestión de audiencias',x,'Organiza personas, equipos y grupos para acompañar mejor el cambio.','RDAIM · DISEÑO','◎')+`<section class="panel"><div class="flex hcx-section-tabs"><button class="${audienceTab==='registro'?'primary':'secondary'}" onclick="audienceTab='registro';render()">Personas</button><button class="${audienceTab!=='registro'?'primary':'secondary'}" onclick="audienceTab='mapa';render()">Distribución y estrategias</button><button class="secondary" type="button" onclick="audQuickNew()">＋ Nueva audiencia</button></div></section>${audienceTab==='registro'?audienceRegistration(x):audienceMap(x,counts)+audDrawerHTML(x)}`}
function audienceRegistrationBase(x){let a=x.audiences.find(a=>a.id===audienceEditing)||{};return `<div class="grid"><section class="panel"><h2>${audienceEditing?'Editar':'Registrar'} audiencia</h2><form onsubmit="saveAudienceV22(event)"><div class="aud-v22-fields"><label>Tipo<select name="kind"><option ${a.kind!=='Grupo'?'selected':''}>Persona</option><option ${a.kind==='Grupo'?'selected':''}>Grupo</option></select></label>${audInput('Nombre / grupo *','name',a.name)}${audInput('Número de personas (grupos)','population',a.population||'','number')}${audInput('Cargo','job',a.job)}${audInput('Dirección','direction',a.direction)}${audInput('Equipo','team',a.team)}${audInput('Correo (opcional)','email',a.email,'email')}<label>Rol dentro del cambio<input name="changeRole" value="${safe(a.changeRole)}" placeholder="Ej. Líder, ejecutor, usuario"></label><label>Capacidad de incidencia${audSelect('authority',AUD_AUTH,a.authority)}</label><label>Posicionamiento${audSelect('position',AUD_POSITION,a.position)}</label><label>Impacto<select name="impact"><option value="">Sin evaluar</option>${['Alto','Medio','Bajo'].map(v=>`<option ${a.impact===v?'selected':''}>${v}</option>`).join('')}</select></label>${audInput('Segmento','segment',a.segment)}</div><label>Impactos específicos<textarea name="specificImpact">${safe(a.specificImpact)}</textarea></label><label>Historial de cambio<textarea name="changeHistory">${safe(a.changeHistory)}</textarea></label><label>Evidencias de clasificación (opcional)<textarea name="classificationEvidence" placeholder="Hechos observados, fuente y fecha">${safe(a.classificationEvidence)}</textarea></label><button class="primary">${audienceEditing?'Guardar cambios':'Agregar audiencia'}</button> ${audienceEditing?'<button type="button" class="secondary" onclick="audienceEditing=null;render()">Cancelar</button>':''}</form></section><section class="panel"><h2>Importar audiencias desde Excel</h2><p class="muted">Carga tu archivo .xlsx directamente, sin convertirlo. La primera hoja debe tener los encabezados en la primera fila; nombre es obligatorio. Revisa la vista previa antes de importar.</p><button class="secondary" onclick="downloadAudienceTemplateV22()">↓ Plantilla CSV (opcional)</button><input type="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" onchange="previewAudienceCSVV22(this)"><div id="aud-v22-import"></div><h3>Audiencias (${x.audiences.length})</h3><div class="aud-v22-list">${x.audiences.map(a=>`<div class="aud-v22-row"><div><strong>${safe(a.name)}</strong><p class="muted">${safe(a.authority||'Sin autoridad')} · ${safe(a.position||'Sin posición')} · ${audQuadrant(a)||'Sin cuadrante'}</p></div><div class="flex"><button class="secondary" onclick="audienceEditing='${safe(a.id)}';render()">Editar</button><button class="secondary aud-danger" onclick="deleteAudienceV23('${safe(a.id)}')">Eliminar</button></div></div>`).join('')||'<div class="empty">No hay audiencias registradas.</div>'}</div></section></div>`}
function saveAudienceV22(e){e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(!d.name.trim())return alert('Indica un nombre');if(d.population&&(!Number.isInteger(Number(d.population))||Number(d.population)<0))return alert('La población debe ser un entero no negativo');let x=current(),a=x.audiences.find(a=>a.id===audienceEditing);if(!a){a={id:'aud-'+crypto.randomUUID()};x.audiences.push(a)}Object.assign(a,d,{name:d.name.trim()});audienceEditing=null;audQuickCreateOpen=false;if(typeof graphSyncAudiences==='function')graphSyncAudiences(x);save();render()}
function deleteAudienceV23(id){
 const x=current(),a=x.audiences.find(a=>a.id===id);if(!a)return;
 const linked=(x.behaviors||[]).filter(b=>(b.audienceIds||[]).includes(id)).length;
 const warning=linked?`\nEstá vinculada a ${linked} comportamiento(s); se quitará esa asociación, pero se conservarán los comportamientos.`:'';
 if(!confirm(`¿Eliminar la audiencia «${a.name}»?${warning}\nEsta acción no se puede deshacer.`))return;
 x.audiences=x.audiences.filter(item=>item.id!==id);
 (x.behaviors||[]).forEach(b=>{if(Array.isArray(b.audienceIds))b.audienceIds=b.audienceIds.filter(aid=>aid!==id)});
 if(audienceEditing===id)audienceEditing=null;if(audienceSelected===id)audienceSelected=null;
 save();render();
}
function audPopulation(a){return a.kind==='Grupo'?Math.max(0,Number(a.population)||0):1}
function audPriority(a){return a.impact==='Alto'&&(a.position==='Probable Resistente'||a.position==='Saboteador Abierto'||a.position==='Saboteador Oculto')}
function audFocus(id){audienceSelected=id;render();document.getElementById('audience-detail-v23')?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function audFilterQuadrant(q){audienceQuadrantFilter=audienceQuadrantFilter===q?'':q;audienceSelected=null;render()}
function audMapSearch(value){audienceFilter=value;const root=document.getElementById('aud-map-results');if(!root)return;root.querySelectorAll('[data-aud-search]').forEach(el=>{el.hidden=!el.dataset.audSearch.includes(value.toLocaleLowerCase('es'))});document.querySelectorAll('.aud-map-label').forEach(el=>{el.hidden=!!value&&!el.dataset.audSearch.includes(value.toLocaleLowerCase('es'))})}
function audSendStrategy(id,q,index){
 const x=current(),a=x.audiences.find(a=>a.id===id),strategy=AUD_STRATEGIES[q]?.[index];if(!a||!strategy)return;
 if(!confirm(`¿Crear una acción pendiente en Implementación para «${a.name}»?\n\n${strategy}`))return;
 x.actions=x.actions||[];
 x.actions.push({name:`${strategy} · ${a.name}`,title:`${strategy} · ${a.name}`,description:`Estrategia orientativa del mapa de audiencias (${q}). Validar pertinencia con evidencias.`,hypothesis:`Dado el posicionamiento registrado de ${a.name}, esperamos que ${strategy.toLocaleLowerCase('es')} favorezca su involucramiento. Hipótesis por validar.`,origin:'Diagnóstico',source:'Mapa de audiencias',audienceId:a.id,audienceName:a.name,quadrant:q,status:'Pendiente',createdAt:new Date().toISOString()});
 save();alert('Acción registrada como pendiente en Implementación. Revisa y completa sus datos allí.');
}
function audienceMapLegacy(x,counts){
 const all=x.audiences||[],positioned=all.filter(a=>audQuadrant(a)),unclassified=all.length-positioned.length;
 const filtered=positioned.filter(a=>!audienceQuadrantFilter||audQuadrant(a)===audienceQuadrantFilter);
 const total=all.reduce((n,a)=>n+audPopulation(a),0),priority=all.filter(audPriority).length;
 const overlaps={};
 const dots=filtered.map(a=>{
  const sc=audScore(a),key=sc.authority+'-'+sc.interest,idx=overlaps[key]||0;overlaps[key]=idx+1;
  const theta=idx*2.39996,r=idx?Math.min(30,9*Math.sqrt(idx)):0;
  const px=12+(sc.interest-4)/6*76,py=88-(sc.authority-5)/5*76;
  const color=a.position==='Promotor'?'#20c5aa':a.position==='Pasivo'?'#efb957':'#ed837f';
  const size=Math.min(30,13+Math.sqrt(audPopulation(a))*2);
  return `<button type="button" class="aud-map-label ${audienceSelected===a.id?'is-selected':''}" data-aud-search="${safe(a.name.toLocaleLowerCase('es'))}" style="left:clamp(5%,calc(${px}% + ${Math.cos(theta)*r}px),95%);top:clamp(6%,calc(${py}% + ${Math.sin(theta)*r}px),94%)" title="${safe(a.name)} · ${safe(a.authority)} · ${safe(a.position)}" onclick="audFocus('${safe(a.id)}')"><span class="aud-map-bubble" style="width:${size}px;height:${size}px;background:${color}"></span><span class="aud-map-name">${safe(a.name)}</span></button>`;
 }).join('');
 const selected=all.find(a=>a.id===audienceSelected);
 const detail=selected?`<section id="audience-detail-v23" class="panel aud-detail"><div class="flex" style="justify-content:space-between"><h3>${safe(selected.name)}</h3><button class="secondary" onclick="audienceSelected=null;render()">Cerrar ×</button></div><p class="muted">${safe(selected.kind||'Persona')} · ${audPopulation(selected)} persona(s) · ${safe(selected.team||selected.direction||'Sin equipo')}</p><p><b>Autoridad:</b> ${safe(selected.authority||'Sin clasificar')} (${audScore(selected).authority??'—'}) · <b>Posicionamiento:</b> ${safe(selected.position||'Sin clasificar')} (${audScore(selected).interest??'—'})</p><p><b>Impacto:</b> ${safe(selected.impact||'Sin evaluar')} · <b>Cuadrante:</b> ${audQuadrant(selected)||'Sin clasificar'}</p>${selected.classificationEvidence?`<p><b>Evidencias:</b> ${safe(selected.classificationEvidence)}</p>`:''}${audPriority(selected)?'<p class="notice">Revisión prioritaria sugerida: impacto alto y posible oposición. Contrasta la clasificación con evidencias.</p>':''}<h3>Estrategias orientativas</h3>${(AUD_STRATEGIES[audQuadrant(selected)]||[]).map((st,i)=>`<div class="aud-strategy-line"><span>${safe(st)}</span><button class="secondary" onclick="audSendStrategy('${safe(selected.id)}','${audQuadrant(selected)}',${i})">+ Llevar a Implementación</button></div>`).join('')||'<p class="muted">Clasifica la audiencia para visualizar estrategias.</p>'}</section>`:'';
 const quadrants=[['Q2','Consultar'],['Q1','Colaborar'],['Q3','Informar'],['Q4','Involucrar']];
 return `<section class="panel"><h2>Mapa y estrategias de audiencias</h2><p class="muted">Explora las audiencias y selecciona un punto para conocer sus características y acciones sugeridas. Puntuaciones según las categorías acordadas; corte alto: 7.</p><div class="aud-kpis"><div><b>${all.length}</b><small>Audiencias</small></div><div><b>${total}</b><small>Personas representadas</small></div><div><b>${priority}</b><small>Para revisión prioritaria</small></div><div><b>${unclassified}</b><small>Sin clasificar</small></div></div><div class="flex"><label class="aud-search">Buscar audiencia<input aria-label="Buscar audiencia" placeholder="Nombre de persona o grupo" value="${safe(audienceFilter)}" oninput="audMapSearch(this.value)"></label><button class="secondary" onclick="audienceQuadrantFilter='';audienceFilter='';render()">Limpiar filtros</button></div><div class="aud-map-v23"><div class="aud-map-quadrants">${quadrants.map(([q,label])=>`<button style="flex-direction:column;justify-content:flex-start;overflow:auto" class="aud-quadrant ${audienceQuadrantFilter===q?'selected':''}" onclick="audFilterQuadrant('${q}')"><span>${q} · ${label}</span><strong>${counts[q]}</strong></button>`).join('')}</div>${dots||'<div class="aud-no-dots">No hay audiencias clasificadas en este filtro.</div>'}<div class="aud-axis-y">Autoridad ↑</div><div class="aud-axis-x">Interés / influencia →</div></div><div class="aud-legend"><span><i style="background:#20c5aa"></i> Promotor</span><span><i style="background:#efb957"></i> Pasivo</span><span><i style="background:#ed837f"></i> Posible oposición</span><span>El tamaño indica población</span></div>${detail}<h3>Audiencias en el mapa</h3><div id="aud-map-results" class="aud-results">${filtered.map(a=>`<button data-aud-search="${safe(a.name.toLocaleLowerCase('es'))}" class="aud-result" onclick="audFocus('${safe(a.id)}')"><b>${safe(a.name)}</b><small>${audQuadrant(a)} · ${safe(a.position)} · ${audPopulation(a)} persona(s)</small></button>`).join('')||'<p class="muted">No hay resultados.</p>'}</div><h3>Estrategias por cuadrante</h3><p class="muted">Selecciona un cuadrante para filtrar sus audiencias. Las estrategias son orientativas y deben contrastarse con evidencias.</p><div class="aud-strategies-grid">${quadrants.map(([q,label])=>`<section class="aud-strategy-card"><button class="aud-strategy-head" onclick="audFilterQuadrant('${q}')"><b>${q} · ${label}</b><span>${counts[q]} persona(s)</span></button>${AUD_STRATEGIES[q].map(s=>`<p>• ${safe(s)}</p>`).join('')}</section>`).join('')}</div></section>`;
}
function audienceStrategies(x,counts){return `<section class="panel"><h2>Estrategias por cuadrante</h2><p class="muted">Orientaciones iniciales: contrasta las acciones con el diagnóstico y la evidencia antes de aplicarlas.</p><div class="grid">${Object.entries(AUD_STRATEGIES).map(([q,items])=>`<section class="panel"><h3>${q} · ${{Q1:'Colaborar',Q2:'Consultar',Q3:'Informar',Q4:'Involucrar'}[q]} (${counts[q]})</h3>${items.map(t=>`<p>• ${safe(t)}</p>`).join('')}</section>`).join('')}</div><h3>Audiencias y recomendaciones</h3>${x.audiences.map(a=>{let q=audQuadrant(a);return `<div class="aud-v22-row"><div><strong>${safe(a.name)}</strong><p class="muted">${q||'Pendiente de clasificación'} · ${safe(a.position||'Sin posición')}</p></div><span>${q?AUD_STRATEGIES[q].map(safe).join(' · '):'Selecciona las categorías para obtener una orientación.'}</span></div>`}).join('')}</section>`}
const AUD_CSV_FIELDS=['nombre','tipo','poblacion','cargo','direccion','equipo','correo','rol_cambio','autoridad','interes_influencia','impacto','segmento','impactos_especificos','historial_cambio','evidencia'];
function downloadAudienceTemplateV22(){let header=AUD_CSV_FIELDS.join(','),example=['Líderes regionales','Grupo','12','Líder','Operaciones','Regional','','Patrocinador','Decisor','Promotor','Alto','','','',''].join(',');let b=new Blob(['\uFEFF'+header+'\r\n'+example],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='HACERLO_plantilla_audiencias_V22.csv';a.click();URL.revokeObjectURL(url)}
let audV22Rows=[];
let audV22ImportInitiative=null;
function audienceImportRecordsV269(data){const normalize=v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().replace(/[\s/]+/g,'_'),keys=data.headers.map(normalize);if(keys.some(k=>!k)||new Set(keys).size!==keys.length)throw Error('Hay encabezados vacíos o repetidos.');if(!keys.includes('nombre'))throw Error('Falta la columna nombre.');if(!data.rows.length)throw Error('El archivo no tiene registros.');if(data.rows.length>2000)throw Error('Máximo 2.000 registros.');const seen=new Set();return data.rows.map((row,i)=>{const d=Object.fromEntries(keys.map((key,j)=>[key,String(row[data.headers[j]]??'').trim()])),errors=[],name=d.nombre.toLocaleLowerCase('es');if(!d.nombre)errors.push('Nombre vacío');if(seen.has(name))errors.push('Nombre repetido');seen.add(name);if(d.autoridad&&!Object.hasOwn(AUD_AUTH,d.autoridad))errors.push('Autoridad no reconocida');if(d.interes_influencia&&!Object.hasOwn(AUD_POSITION,d.interes_influencia))errors.push('Interés/influencia no reconocido');if(d.poblacion&&!/^\d+$/.test(d.poblacion))errors.push('Población inválida');if(d.tipo&&!['Persona','Grupo'].includes(d.tipo))errors.push('Tipo debe ser Persona o Grupo');if(d.impacto&&!['Alto','Medio','Bajo'].includes(d.impacto))errors.push('Impacto debe ser Alto, Medio o Bajo');return {d,errors,line:i+2};});}
let audExcelSetup=null;
const AUD_IMPORT_LABELS={codigo:'Código de persona',vicepresidencia:'Vicepresidencia',nombre:'Nombre / grupo',tipo:'Tipo: Persona o Grupo',poblacion:'Número de personas',cargo:'Cargo',direccion:'Dirección',equipo:'Equipo',correo:'Correo',rol_cambio:'Rol dentro del cambio',autoridad:'Autoridad',interes_influencia:'Interés / influencia',impacto:'Impacto',segmento:'Segmento',audiencia:'Audiencia de destino',impactos_especificos:'Impactos específicos',historial_cambio:'Historial de cambio',evidencia:'Evidencias'};
function audSuggestImportField(header){const k=String(header).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[\s/]+/g,'_'),aliases={codigo_persona:'codigo',id:'codigo',puesto:'cargo',rol_conectados_para_crecer:'audiencia',name:'nombre',nombres:'nombre',nombre_completo:'nombre',nombre_grupo:'nombre',numero_de_personas:'poblacion',rol:'rol_cambio',rol_dentro_del_cambio:'rol_cambio',email:'correo',area:'direccion',audiencia_destino:'audiencia',grupo:'audiencia'};return Object.hasOwn(AUD_IMPORT_LABELS,k)?k:aliases[k]||'';}
async function previewAudienceCSVV22(input){const target=document.getElementById('aud-v22-import'),initiativeId=current().id;audV22Rows=[];audV22ImportInitiative=null;audExcelSetup=null;if(!input.files.length)return;try{const file=input.files[0];if(file.size>10*1024*1024)throw Error('Máximo 10 MB.');if(!/\.(xlsx|csv)$/i.test(file.name))throw Error('Selecciona Excel .xlsx o CSV.');const data=/\.xlsx$/i.test(file.name)?await eeReadXLSX(file):EE.records(EE.parseCSV(await file.text()));if(current().id!==initiativeId||document.getElementById('aud-v22-import')!==target)return;if(!data.rows.length||data.rows.length>10000)throw Error('El archivo debe tener entre 1 y 10.000 filas.');audExcelSetup={data,initiativeId,fileName:file.name,mode:'personas'};target.innerHTML=audImportMappingHTML(data,file.name,current());audRefreshAudienceAssignments();}catch(e){target.textContent='Error: '+e.message;}}
function audImportMappingHTML(data,fileName,x){return `<h3>Configurar columnas</h3><label>Qué vas a importar<select onchange="audSetImportMode(this.value)"><option value="personas"${audExcelSetup?.mode!=='audiencias'?' selected':''}>Personas y asignarlas a audiencias</option><option value="audiencias"${audExcelSetup?.mode==='audiencias'?' selected':''}>Crear o actualizar audiencias</option></select></label><p>${safe(fileName)} · ${data.rows.length} filas</p><form onsubmit="audValidateMappedImport(event)">${data.headers.map((header,i)=>`<label>${safe(header)}<select data-aud-map="${i}" onchange="audRefreshAudienceAssignments()"><option value="">No importar</option>${Object.entries(AUD_IMPORT_LABELS).map(([key,label])=>`<option value="${key}"${audSuggestImportField(header)===key?' selected':''}>${label}</option>`).join('')}</select></label>`).join('')}<div id="aud-person-assignments"></div><details><summary>Asignación masiva (opcional)</summary><label>Rol dentro del cambio<input name="bulkRole" placeholder="Ej. Usuario, líder, patrocinador"></label><label>Audiencia de destino<select name="bulkAudience"><option value="">Sin asignación común</option>${(x.audiences||[]).filter(a=>!a.parentAudienceId).map(a=>`<option value="${safe(a.id)}">${safe(a.name)}</option>`).join('')}</select></label><label><input type="checkbox" name="overwrite"> Reemplazar también los roles y audiencias que ya vienen en el archivo</label><p class="muted">Por defecto, los valores del archivo tienen prioridad. La audiencia de destino debe existir en esta iniciativa.</p></details><button class="primary">Validar y ver vista previa</button></form><div id="aud-mapped-preview"></div>`;}
function audBuildMappedImport(data,mapping,bulk,x){const selected=mapping.filter(Boolean);if(new Set(selected).size!==selected.length)throw Error('Cada campo debe asignarse a una sola columna.');if(!selected.includes('nombre'))throw Error('Relaciona una columna con Nombre / grupo.');const rows=data.rows.map(row=>{const record={};mapping.forEach((key,i)=>{if(key)record[key]=String(row[data.headers[i]]??'').trim();});if(bulk.role&&(bulk.overwrite||!record.rol_cambio))record.rol_cambio=bulk.role;if(bulk.audience&&(bulk.overwrite||!record.audiencia))record.audiencia=bulk.audience;return record;});const keys=[...new Set(rows.flatMap(Object.keys))],parsed=audienceImportRecordsV269({headers:keys,rows});for(const row of parsed){if(row.d.audiencia){const dest=(x.audiences||[]).find(a=>a.id===row.d.audiencia||a.name.trim().toLocaleLowerCase('es')===row.d.audiencia.toLocaleLowerCase('es'));if(!dest)row.errors.push('Audiencia de destino no encontrada');else if(dest.name.trim().toLocaleLowerCase('es')===row.d.nombre.toLocaleLowerCase('es'))row.errors.push('La audiencia no puede asignarse a sí misma');else row.d.parent_audience_id=dest.id;}}return parsed;}
function audValidateMappedImport(e){e.preventDefault();const target=document.getElementById('aud-mapped-preview'),st=audExcelSetup;audV22Rows=[];if(!st||st.initiativeId!==current().id)return;try{const fd=new FormData(e.target),mapping=[...e.target.querySelectorAll('[data-aud-map]')].map(el=>el.value);const bulk={role:String(fd.get('bulkRole')||'').trim(),audience:String(fd.get('bulkAudience')||''),overwrite:fd.get('overwrite')==='on'},assignments=Object.fromEntries([...e.target.querySelectorAll('[data-person-assignment]')].map(el=>[el.dataset.personAssignment,el.value]));audV22Rows=st.mode==='personas'?audBuildPeopleImport(st.data,mapping,bulk,current(),assignments):audBuildMappedImport(st.data,mapping,bulk,current());audV22ImportInitiative=st.initiativeId;audRenderMappedPreview(target,st.fileName);}catch(err){target.textContent='Error: '+err.message;}}
function audRenderMappedPreview(target,fileName){const valid=audV22Rows.filter(r=>!r.errors.length);target.innerHTML=`<p>${safe(fileName)} · ${valid.length} filas válidas · ${audV22Rows.length-valid.length} con errores</p><details><summary>Vista previa de audiencias</summary><div style="max-height:300px;overflow:auto"><table><thead><tr><th>Fila</th><th>Nombre</th><th>Tipo</th><th>Población</th><th>Rol</th><th>Audiencia de destino</th><th>Resultado</th></tr></thead><tbody>${audV22Rows.slice(0,100).map(r=>`<tr><td>${r.line}</td><td>${safe(r.d.nombre||r.d.codigo)}</td><td>${safe(r.d.tipo||'Persona')}</td><td>${safe(r.d.poblacion||'')}</td><td>${safe(r.d.rol_cambio||'')}</td><td>${safe((current().audiences||[]).find(a=>a.id===r.d.parent_audience_id)?.name||'')}</td><td>${r.errors.length?safe(r.errors.join(', ')):'Válida'}</td></tr>`).join('')}</tbody></table></div>${audV22Rows.length>100?'<small>Vista previa: primeras 100 filas. Se validaron todas las filas.</small>':''}</details>${audV22Rows.filter(r=>r.errors.length).slice(0,10).map(r=>`<p class="notice">Fila ${r.line}: ${safe(r.errors.join(', '))}</p>`).join('')}<label>Duplicados por ${audExcelSetup?.mode==='personas'?'código de persona':'nombre'}<select id="aud-v22-mode"><option value="skip">Omitir existentes</option><option value="update">Actualizar existentes</option></select></label><button class="primary" ${valid.length?'':'disabled'} onclick="commitAudienceCSVV22()">Importar ${valid.length} ${audExcelSetup?.mode==='personas'?'personas':'audiencias'} válidas</button>`;}

function commitAudienceCSVV22(){if(audExcelSetup?.mode==='personas')return audCommitPeopleImport();let x=current();if(audV22ImportInitiative!==x.id){audV22Rows=[];return alert('Vuelve a cargar el archivo en esta iniciativa.');}let mode=document.getElementById('aud-v22-mode').value,added=0,updated=0;let map={nombre:'name',tipo:'kind',poblacion:'population',cargo:'job',direccion:'direction',equipo:'team',correo:'email',rol_cambio:'changeRole',autoridad:'authority',interes_influencia:'position',impacto:'impact',segmento:'segment',impactos_especificos:'specificImpact',historial_cambio:'changeHistory',evidencia:'classificationEvidence',parent_audience_id:'parentAudienceId'};for(let {d,errors} of audV22Rows){if(errors.length)continue;let a=x.audiences.find(a=>a.name.trim().toLocaleLowerCase('es')===d.nombre.trim().toLocaleLowerCase('es'));if(a&&mode==='skip')continue;if(!a){a={id:'aud-'+crypto.randomUUID()};x.audiences.push(a);added++}else updated++;for(let [from,to] of Object.entries(map))if(d[from]!==undefined)a[to]=d[from]}audV22Rows=[];audExcelSetup=null;save();alert(`Importadas: ${added} nuevas, ${updated} actualizadas`);render()}

function audienceRegistration(x){const html=audienceRegistrationBase(x),start=html.indexOf('<form'),end=html.indexOf('</form>',start)+7,i=html.indexOf('<p class="muted">Carga tu archivo'),j=html.indexOf('<h3>Audiencias',i),list=html.slice(j,html.lastIndexOf('</section>'));return `<section class="panel aud-setup"><h2>Gestionar audiencias</h2><details ${audienceEditing||audQuickCreateOpen||!x.audiences.length?'open':''}><summary class="secondary">${audienceEditing?'Editar audiencia':'＋ Crear audiencia'}</summary>${html.slice(start,end)}</details><details><summary class="secondary">↑ Importar Excel</summary>${html.slice(i,j)}</details><details><summary class="secondary">Ver audiencias · ${x.audiences.length}</summary>${list}</details></section>`+audPeoplePanel(x);}

function audSetImportMode(mode){if(!audExcelSetup)return;audExcelSetup.mode=mode==='audiencias'?'audiencias':'personas';audV22Rows=[];document.getElementById('aud-v22-import').innerHTML=audImportMappingHTML(audExcelSetup.data,audExcelSetup.fileName,current());audRefreshAudienceAssignments();}
function audRefreshAudienceAssignments(){const st=audExcelSetup,target=document.getElementById('aud-person-assignments');if(!st||!target)return;audV22Rows=[];const el=[...document.querySelectorAll('[data-aud-map]')].find(el=>el.value==='audiencia');if(!el||st.mode!=='personas'){target.innerHTML='';return;}const header=st.data.headers[Number(el.dataset.audMap)],values=[...new Set(st.data.rows.map(r=>String(r[header]??'').trim()).filter(Boolean))],audiences=current().audiences||[];target.innerHTML=`<details open><summary>Relacionar roles del Excel con audiencias</summary>${values.map(value=>{const found=audiences.find(a=>a.name.trim().toLocaleLowerCase('es')===value.toLocaleLowerCase('es')||a.id===value);return `<label>${safe(value)}<select data-person-assignment="${safe(value)}"><option value="">Selecciona una audiencia existente</option>${audiences.map(a=>`<option value="${safe(a.id)}"${found?.id===a.id?' selected':''}>${safe(a.name)}</option>`).join('')}</select></label>`;}).join('')}</details>`;}
function audBuildPeopleImport(data,mapping,bulk,x,assignments={}){const fields=mapping.filter(Boolean);if(new Set(fields).size!==fields.length)throw Error('Cada campo debe usarse una sola vez.');if(!fields.includes('codigo'))throw Error('Relaciona la columna Código de persona.');const seen=new Set();return data.rows.map((row,i)=>{const d={};mapping.forEach((field,j)=>{if(field)d[field]=String(row[data.headers[j]]??'').trim();});const errors=[],key=String(d.codigo||'').toLocaleLowerCase('es');if(!key)errors.push('Código vacío');if(seen.has(key))errors.push('Código repetido en el archivo');seen.add(key);if(bulk.role&&(bulk.overwrite||!d.rol_cambio))d.rol_cambio=bulk.role;const fileAudience=d.audiencia||'';if(fileAudience&&!d.rol_cambio)d.rol_cambio=fileAudience;const destination=bulk.audience&&(bulk.overwrite||!fileAudience)?bulk.audience:(assignments[fileAudience]||fileAudience);const audience=(x.audiences||[]).find(a=>a.id===destination||a.name.trim().toLocaleLowerCase('es')===destination.toLocaleLowerCase('es'));if(!audience)errors.push('Selecciona una audiencia de destino');else d.parent_audience_id=audience.id;return {d,errors,line:i+2};});}
function audCommitPeopleImport(){const x=current(),st=audExcelSetup;if(!st||st.initiativeId!==x.id||audV22ImportInitiative!==x.id)return alert('Vuelve a cargar el archivo en esta iniciativa.');const mode=document.getElementById('aud-v22-mode').value;x.audiencePeople ||= [];let added=0,updated=0;for(const {d,errors} of audV22Rows){if(errors.length)continue;if(!x.audiences.some(a=>a.id===d.parent_audience_id))return alert('La audiencia de destino ya no existe. Vuelve a validar.');}for(const {d,errors} of audV22Rows){if(errors.length)continue;let person=x.audiencePeople.find(p=>p.code.trim().toLocaleLowerCase('es')===d.codigo.toLocaleLowerCase('es'));if(person&&mode==='skip')continue;if(!person){person={id:'person-'+crypto.randomUUID(),code:d.codigo,createdAt:new Date().toISOString()};x.audiencePeople.push(person);added++;}else updated++;const map={codigo:'code',nombre:'name',cargo:'job',vicepresidencia:'vicepresidency',direccion:'direction',equipo:'team',correo:'email',rol_cambio:'changeRole',parent_audience_id:'audienceId',segmento:'segment',autoridad:'authority',interes_influencia:'position',impacto:'impact',evidencia:'classificationEvidence'};for(const [key,field] of Object.entries(map))if(d[key]!==undefined)person[field]=d[key];person.updatedAt=new Date().toISOString();}audV22Rows=[];audExcelSetup=null;save();alert(`Personas importadas: ${added} nuevas, ${updated} actualizadas. Las audiencias existentes se conservan.`);render();}
// V2.6.13: valoración individual, selección masiva y distribución filtrada.
let audPeopleExpanded=false;
let audPersonFilters={audienceId:'',team:'',direction:'',search:''},audPersonSelection=new Set(),audPersonEditing=null,audPeoplePage=0;
function audPersonFields(p={},bulk=false){return `<div class="aud-v22-fields"><label>Capacidad de incidencia${audSelect('authority',AUD_AUTH,p.authority)}</label><label>Posicionamiento${audSelect('position',AUD_POSITION,p.position)}</label><label>Impacto<select name="impact"><option value="">${bulk?'No modificar':'Sin evaluar'}</option>${['Alto','Medio','Bajo'].map(v=>`<option ${p.impact===v?'selected':''}>${v}</option>`).join('')}</select></label>${audInput('Segmento','segment',p.segment||'')}<label>Audiencia<select name="audienceId"><option value="">${bulk?'No modificar':'Sin audiencia'}</option>${(current().audiences||[]).map(a=>`<option value="${safe(a.id)}" ${a.id===p.audienceId?'selected':''}>${safe(a.name)}</option>`).join('')}</select></label></div>${bulk?'<small>Los campos vacíos conservan el valor actual de cada persona.</small>':''}<label>Evidencias<textarea name="classificationEvidence">${safe(p.classificationEvidence||'')}</textarea></label>`;}
function audApplyPersonChanges(x,ids,data,bulk){const allowed={authority:Object.keys(AUD_AUTH),position:Object.keys(AUD_POSITION),impact:['Alto','Medio','Bajo'],audienceId:(x.audiences||[]).map(a=>a.id)};for(const [k,values] of Object.entries(allowed))if(data[k]&&!values.includes(data[k]))throw Error('Valor inválido: '+k);let n=0;for(const p of x.audiencePeople||[]){if(!ids.has(p.id))continue;for(const k of ['authority','position','impact','segment','audienceId','classificationEvidence'])if(data[k]!==undefined&&(!bulk||data[k]!==''))p[k]=data[k];p.updatedAt=new Date().toISOString();n++;}return n;}
function audPeopleList(x,audienceId='',search='',page=0){return audPeoplePanel(x);}
function audShowPeople(){render();}
function audDistribution(x){const rows=audPersonRows(x),counts={Q1:0,Q2:0,Q3:0,Q4:0,unclassified:0},groups={};for(const p of rows){const q=audQuadrant(p)||'unclassified';counts[q]++;const id=p.audienceId||'';groups[id] ||= {Q1:0,Q2:0,Q3:0,Q4:0,unclassified:0};groups[id][q]++;}return {rows,counts,groups};}
function audienceStrategicMap(x,counts){if(!(x.audiencePeople||[]).length)return audienceMapLegacy(x,counts);const d=audDistribution(x),qs=[['Q2','Consultar'],['Q1','Colaborar'],['Q3','Informar'],['Q4','Involucrar']],name=id=>x.audiences.find(a=>a.id===id)?.name||'Sin audiencia';return `<section class="panel"><h2>Distribución de personas</h2>${audPersonFilterHTML(x)}<p><b>${d.rows.length}</b> personas · <b>${d.counts.unclassified}</b> sin clasificar</p><div class="aud-map-v23"><div class="aud-map-quadrants">${qs.map(([q,label])=>`<button style="flex-direction:column;justify-content:flex-start;overflow:auto" class="aud-quadrant ${audienceQuadrantFilter===q?'selected':''}" onclick="audFilterQuadrant('${q}')"><span>${q} · ${label}</span><strong>${d.counts[q]} personas</strong>${Object.entries(d.groups).filter(([id,c])=>c[q]).map(([id,c])=>`<small>${safe(name(id))}: ${c[q]}</small>`).join('')}</button>`).join('')}</div><div class="aud-axis-y">Autoridad ↑</div><div class="aud-axis-x">Interés / influencia →</div></div><small>Autoridad e interés/influencia: alto desde 7. Cada persona cuenta una vez. Las valoraciones de la audiencia no se asignan automáticamente a sus personas.</small><details ${audienceQuadrantFilter?'open':''}><summary>Ver personas ${audienceQuadrantFilter||'del mapa'}</summary><label>Cuadrante<select onchange="audienceQuadrantFilter=this.value;render()"><option value="">Todos</option>${[...qs,['unclassified','Sin clasificar']].map(([q,n])=>`<option value="${q}" ${audienceQuadrantFilter===q?'selected':''}>${q==='unclassified'?n:q+' · '+n}</option>`).join('')}</select></label><div style="max-height:360px;overflow:auto">${d.rows.filter(p=>!audienceQuadrantFilter||(audQuadrant(p)||'unclassified')===audienceQuadrantFilter).map(p=>`<p><button class="secondary" onclick="audienceTab='registro';audPersonEdit('${safe(p.id)}')">${safe(p.name||p.code)}</button> · ${safe(name(p.audienceId))} · ${safe(p.direction||'—')} / ${safe(p.team||'—')} · ${audQuadrant(p)||'Sin clasificar'}</p>`).join('')||'<p>No hay personas en este filtro.</p>'}</div></details><details><summary>Estrategias por cuadrante</summary><p class="muted">Selecciona una tarjeta para ver las personas de ese cuadrante. Estas estrategias sirven como guía para decidir cómo acompañarlas.</p><div class="aud-strategies-grid">${qs.map(([q,n])=>`<section class="aud-strategy-card"><button type="button" class="aud-strategy-head" onclick="audFilterQuadrant('${q}')"><b>${q} · ${n}</b><span>${d.counts[q]} persona(s)</span></button><p class="muted">${({Q1:'Alta autoridad y alto interés/influencia. Involucrar en las decisiones y trabajar en conjunto.',Q2:'Alta autoridad y menor interés/influencia. Escuchar sus inquietudes y consultar decisiones clave.',Q3:'Menor autoridad y menor interés/influencia. Mantener información clara y observar cómo evoluciona su participación.',Q4:'Menor autoridad y alto interés/influencia. Dar espacios para participar y aportar.'})[q]}</p>${AUD_STRATEGIES[q].map(st=>`<p>• ${safe(st)}</p>`).join('')}</section>`).join('')}</div></details></section>`;}

// V2.7: adopción por comportamiento. Son valoraciones documentadas, sin inferir intención.
const AUD_ADOPTION_STAGES={
 unknown:{label:'Sin evidencia suficiente',color:'#9db0c3',help:'No hay evidencia suficiente para asignar otro estado.'},
 understands:{label:'Reconoce y comprende',color:'#69b7ff',help:'Explica qué debe hacer y en qué situación. No demuestra todavía ejecución.'},
 tries:{label:'Prueba',color:'#edbd69',help:'Ha ejecutado el comportamiento en una prueba o con orientación.'},
 performs:{label:'Realiza',color:'#5bd5d1',help:'Ejecuta el comportamiento de forma autónoma cuando corresponde.'},
 sustains:{label:'Sostiene',color:'#6ee3a7',help:'Repite el comportamiento con la frecuencia y durante el periodo definidos para él.'}
};
const AUD_ADOPTION_CONTEXTS={observed:'Hubo oportunidad de observar',noOpportunity:'No hubo oportunidad',barriers:'Hubo barreras'};
let audPeopleView='adoption',audBehaviorId='',audDistributionView='strategic',audDrawerMode='',audDrawerBehaviorId='',audUIInitiative=null;
function audBehaviorName(b){return b?.name||b?.behavior||'Comportamiento sin nombre';}
function audApplicable(b,p){return !!b&&(b.scope!=='specific'||(b.audienceIds||[]).includes(p.audienceId));}
function audAdoptionBehaviors(x,p=null){return (x.behaviors||[]).filter(b=>b.id&&(!p||audApplicable(b,p)));}
function audCurrentBehavior(x){return (x.behaviors||[]).find(b=>b.id===audBehaviorId)||null;}
function audInitPeopleUI(x){
 if(audUIInitiative!==x.id){audUIInitiative=x.id;audPersonFilters={audienceId:'',team:'',direction:'',search:''};audPersonSelection.clear();audPeoplePage=0;audPeopleExpanded=false;audPersonEditing=null;audDrawerMode='';audBehaviorId='';audDrawerBehaviorId='';audienceQuadrantFilter='';}
 const missing=(x.behaviors||[]).some(b=>!b.id);if(missing&&typeof ensureBehaviorIds==='function'){ensureBehaviorIds(x);save();}
 if(audBehaviorId&&!audViewBehaviors(x).some(b=>b.id===audBehaviorId)){audBehaviorId='';audPersonFilters.adoptionState='';}
}
function audLatestAdoption(p,behaviorId){
 return (p.adoptionHistory||[]).filter(r=>r.behaviorId===behaviorId&&Object.hasOwn(AUD_ADOPTION_STAGES,r.stage)).reduce((latest,r)=>!latest||r.observedOn>latest.observedOn||(r.observedOn===latest.observedOn&&r.recordedAt>=latest.recordedAt)?r:latest,null);
}
function audAdoptionState(p,b){if(!b||!audApplicable(b,p))return 'notApplicable';return audLatestAdoption(p,b.id)?.stage||'unknown';}
function audLocalDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function audDateValid(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===v;}
function audRecordAdoption(x,ids,data,bulk=false){
 const b=(x.behaviors||[]).find(b=>b.id===data.behaviorId);if(!b)throw Error('Selecciona un comportamiento vigente de Diseño.');
 if(!Object.hasOwn(AUD_ADOPTION_STAGES,data.stage))throw Error('Selecciona un estado de adopción.');
 if(!audDateValid(data.observedOn)||data.observedOn>audLocalDate())throw Error('Indica una fecha válida que no esté en el futuro.');
 const evidence=String(data.evidence||'').trim(),source=String(data.source||'').trim();
 if(!evidence||!source)throw Error('Describe lo observado e indica la fuente.');
 if(!Object.hasOwn(AUD_ADOPTION_CONTEXTS,data.context))throw Error('Indica si hubo oportunidad de observar.');
 if(data.context==='noOpportunity'&&data.stage!=='unknown')throw Error('Sin oportunidad de observar, registra Sin evidencia suficiente.');
 if(data.stage==='sustains'&&!String(b.adoptionCriteria||'').trim())throw Error('Define primero el criterio de Sostiene para este comportamiento.');
 if(bulk&&data.bulkEvidence!=='on')throw Error('Confirma que la evidencia corresponde a cada persona seleccionada.');
 const parseCount=(v,label)=>{if(v===undefined||v==='')return null;const n=Number(v);if(!Number.isInteger(n)||n<0)throw Error(label+' debe ser un entero no negativo.');return n;};
 const opportunities=parseCount(data.opportunities,'Oportunidades'),executions=parseCount(data.executions,'Ejecuciones');
 if(opportunities!==null&&executions!==null&&executions>opportunities)throw Error('Las ejecuciones no pueden superar las oportunidades.');
 if(opportunities===0&&data.stage!=='unknown')throw Error('Con cero oportunidades, registra Sin evidencia suficiente.');
 if(data.context==='noOpportunity'&&((opportunities||0)>0||(executions||0)>0))throw Error('Sin oportunidad no puede tener oportunidades o ejecuciones mayores que cero.');
 if(['tries','performs','sustains'].includes(data.stage)&&executions===0)throw Error('Para este estado debe haber ejecución observada.');
 if(data.autonomy&&!['supported','independent'].includes(data.autonomy))throw Error('Selecciona una autonomía válida.');
 if(['performs','sustains'].includes(data.stage)&&data.autonomy!=='independent')throw Error('Realiza y Sostiene requieren ejecución autónoma.');
 const selected=(x.audiencePeople||[]).filter(p=>ids.has(p.id)),eligible=selected.filter(p=>audApplicable(b,p));
 if(!eligible.length)throw Error('El comportamiento no aplica a las personas seleccionadas.');
 const stamp=new Date().toISOString();const entries=eligible.map(p=>({p,record:{id:'adopt-'+crypto.randomUUID(),behaviorId:b.id,behaviorName:audBehaviorName(b),stage:data.stage,observedOn:data.observedOn,evidence,source,context:data.context,barriers:String(data.barriers||'').trim(),opportunities,executions,autonomy:data.autonomy||'',criteriaSnapshot:String(b.adoptionCriteria||''),recordedAt:stamp,mode:bulk?'bulk':'individual'}}));
 for(const {p,record} of entries){p.adoptionHistory ||= [];p.adoptionHistory.push(record);p.updatedAt=stamp;}
 return {updated:eligible.length,skipped:selected.length-eligible.length};
}
function audAdoptionSummary(x,behaviorId,rows=audPersonRows(x)){
 const b=(x.behaviors||[]).find(b=>b.id===behaviorId),counts=Object.fromEntries(Object.keys(AUD_ADOPTION_STAGES).map(k=>[k,0]));let notApplicable=0;
 for(const p of rows){const state=audAdoptionState(p,b);if(state==='notApplicable')notApplicable++;else counts[state]++;}
 return {counts,notApplicable,total:rows.length-notApplicable,rows};
}
function audStateBadge(p,b){const state=audAdoptionState(p,b),meta=AUD_ADOPTION_STAGES[state];return meta?`<span class="aud-status" style="--aud-state:${meta.color}">${meta.label}</span>`:'<span class="muted">No aplica</span>';}
function audArgs(v){return safe(JSON.stringify(String(v)));}
function audUIRender(){const y=typeof window!=='undefined'?window.scrollY:0;render();if(typeof window!=='undefined')window.scrollTo(0,y);audMountDrawer();}
function audChangePeopleView(view){audPeopleView=['position','authority','adoption'].includes(view)?view:'adoption';audPersonFilters={...audPersonFilters,position:'',authority:'',adoptionState:''};audPeoplePage=0;audPersonSelection.clear();audUIRender();}
function audChangeBehavior(id){audBehaviorId=id;audPersonFilters.adoptionState='';audPeoplePage=0;audPersonSelection.clear();audUIRender();}
function audPersonRows(x){return (x.audiencePeople||[]).filter(p=>Object.entries(audPersonFilters).every(([k,v])=>{
 if(!v)return true;if(k==='search')return (String(p.code||'')+' '+(p.name||'')).toLocaleLowerCase('es').includes(v.toLocaleLowerCase('es'));
 if(k==='quadrant')return (audQuadrant(p)||'unclassified')===v;
 if(k==='adoptionState')return audAdoptionState(p,audCurrentBehavior(x))===v;
 return (p[k]||'unclassified')===v;
 }));}
function audPersonFilter(k,v){audPersonFilters[k]=v;audPeoplePage=0;audPersonSelection.clear();audUIRender();}
function audClearPeopleFilters(){audPersonFilters={audienceId:'',direction:'',team:'',search:''};audPeoplePage=0;audPersonSelection.clear();audUIRender();}
function audFilterSelect(key,label,options,empty='Todos'){
 return `<label>${label}<select onchange="audPersonFilter('${key}',this.value)"><option value="">${empty}</option>${options.map(([v,n])=>`<option value="${safe(v)}" ${audPersonFilters[key]===v?'selected':''}>${safe(n)}</option>`).join('')}</select></label>`;
}
function audPersonFilterHTML(x){
 const values=k=>[...new Set((x.audiencePeople||[]).map(p=>p[k]).filter(Boolean))].sort().map(v=>[v,v]);
 const active=Object.entries(audPersonFilters).filter(([,v])=>v),labels={audienceId:'Audiencia',direction:'Dirección',team:'Equipo',search:'Persona',position:'Posicionamiento',authority:'Incidencia',impact:'Impacto',quadrant:'Cuadrante',adoptionState:'Adopción'};
 const text=(k,v)=>k==='audienceId'?(x.audiences||[]).find(a=>a.id===v)?.name||'Sin audiencia':k==='adoptionState'?(AUD_ADOPTION_STAGES[v]?.label||'No aplica'):v==='unclassified'?'Sin clasificar':v;
 return `<div class="aud-filterbar"><label>Buscar persona<input placeholder="Código o nombre" value="${safe(audPersonFilters.search||'')}" onchange="audPersonFilter('search',this.value)"></label>${audFilterSelect('audienceId','Audiencia',(x.audiences||[]).map(a=>[a.id,a.name]),'Todas')}<details class="aud-more-filters" ${active.some(([k])=>['direction','team','impact','quadrant','position','authority'].includes(k))?'open':''}><summary class="secondary">Más filtros</summary><div class="aud-filtergrid">${audFilterSelect('direction','Dirección',values('direction'),'Todas')}${audFilterSelect('team','Equipo',values('team'))}${audFilterSelect('impact','Impacto',['Alto','Medio','Bajo'].map(v=>[v,v]))}${audFilterSelect('authority','Capacidad de incidencia',Object.keys(AUD_AUTH).map(v=>[v,v]).concat([['unclassified','Sin clasificar']]))}${audFilterSelect('position','Posicionamiento',Object.keys(AUD_POSITION).map(v=>[v,v]).concat([['unclassified','Sin clasificar']]))}${audFilterSelect('quadrant','Cuadrante',[['Q1','Q1 · Colaborar'],['Q2','Q2 · Consultar'],['Q3','Q3 · Informar'],['Q4','Q4 · Involucrar'],['unclassified','Sin clasificar']])}</div></details><button class="secondary" onclick="audClearPeopleFilters()">Limpiar filtros</button></div>${active.length?`<div class="aud-active-filters">${active.map(([k,v])=>`<button class="secondary" onclick="audPersonFilter(${audArgs(k)},'')">${safe(labels[k]||k)}: ${safe(text(k,v))} ×</button>`).join('')}</div>`:''}`;
}
function audViewBehaviors(x){return audAdoptionBehaviors(x).filter(b=>!audPersonFilters.audienceId||audApplicable(b,{audienceId:audPersonFilters.audienceId}));}
function audAssignedSummary(x,p){const behaviors=audAdoptionBehaviors(x,p),assessed=behaviors.filter(b=>{const r=audLatestAdoption(p,b.id);return r&&r.stage!=='unknown';}).length;return {total:behaviors.length,assessed,behaviors};}
function audPersonAdoptionCell(x,p,b){if(b)return audStateBadge(p,b);const summary=audAssignedSummary(x,p);return summary.total?`<span>${summary.assessed} de ${summary.total} valorados</span><small class="muted">Asignados por su audiencia</small>`:'<span class="muted">Sin comportamientos asignados</span>';}
function audDrawerChoices(x,p=null){return p?audAdoptionBehaviors(x,p):audAdoptionBehaviors(x).filter(b=>(x.audiencePeople||[]).some(v=>audPersonSelection.has(v.id)&&audApplicable(b,v)));}
function audBehaviorPicker(x,drawer=false,p=null){const list=drawer?audDrawerChoices(x,p):audViewBehaviors(x),id=drawer?audDrawerBehaviorId:audBehaviorId;return `<label>${drawer?'Comportamientos asignados por audiencia':'Ver comportamiento'}<select ${drawer?'':'id="aud-behavior-picker"'} onchange="${drawer?'audDrawerBehaviorChange':'audChangeBehavior'}(this.value)">${drawer?(!list.length?'<option value="">Sin comportamientos asignados a esta audiencia</option>':''):'<option value="">Todos los comportamientos de la audiencia</option>'}${list.map(b=>`<option value="${safe(b.id)}" ${b.id===id?'selected':''}>${safe(audBehaviorName(b))}</option>`).join('')}</select></label>`;}
function audAssignedBehaviorsHTML(x,p){const summary=audAssignedSummary(x,p);return `<details><summary>Comportamientos de su audiencia · ${summary.total}</summary><p class="muted">Se asignan automáticamente desde Diseño. Puedes valorar cada uno por separado.</p>${summary.behaviors.map(b=>`<article><button type="button" class="secondary" onclick="audChooseAssignedBehavior(${audArgs(b.id)})">${safe(audBehaviorName(b))}</button> ${audStateBadge(p,b)}</article>`).join('')||'<p>Esta audiencia todavía no tiene comportamientos asignados.</p>'}</details>`;}
function audChooseAssignedBehavior(id){const select=document.querySelector('#aud-person-drawer section select');if(select)select.value=id;audDrawerBehaviorChange(id);}

function audPeoplePanel(x){
 const rows=audPersonRows(x),pages=Math.max(1,Math.ceil(rows.length/30)),b=audCurrentBehavior(x);audPeoplePage=Math.min(audPeoplePage,pages-1);
 const selected=(x.audiencePeople||[]).filter(p=>audPersonSelection.has(p.id));
 const viewLabel={position:'Posicionamiento',authority:'Capacidad de incidencia',adoption:'Adopción'}[audPeopleView];
 return `<section class="panel aud-people-panel"><details ${audPeopleExpanded?'open':''} ontoggle="audPeopleExpanded=this.open"><summary class="secondary"><b>Personas asignadas a audiencias · ${(x.audiencePeople||[]).length}</b></summary><div class="aud-viewbar"><label>Qué quieres consultar<select onchange="audChangePeopleView(this.value)">${[['adoption','Adopción por comportamiento'],['position','Posicionamiento'],['authority','Capacidad de incidencia']].map(([v,n])=>`<option value="${v}" ${v===audPeopleView?'selected':''}>${n}</option>`).join('')}</select></label>${audPeopleView==='adoption'?audBehaviorPicker(x):''}</div>${audPersonFilterHTML(x)}${audPeopleView==='adoption'&&b?audFilterSelect('adoptionState','Estado de adopción',Object.entries(AUD_ADOPTION_STAGES).map(([k,v])=>[k,v.label]).concat([['notApplicable','No aplica']])):''}<div class="aud-list-toolbar"><span>${rows.length} personas en este filtro</span><button class="secondary" onclick="audSelectFiltered()">Seleccionar todas las del filtro</button></div><div id="aud-selection-tools">${audSelectionTools(selected.length)}</div><div class="aud-compact-table"><table><thead><tr><th class="aud-check-cell"><span aria-label="Seleccionar">✓</span></th><th>Persona</th><th>Audiencia</th><th>${viewLabel}</th><th class="aud-action-cell">Ficha</th></tr></thead><tbody>${rows.slice(audPeoplePage*30,audPeoplePage*30+30).map(p=>`<tr><td class="aud-check-cell"><input type="checkbox" aria-label="Seleccionar ${safe(p.name||p.code)}" ${audPersonSelection.has(p.id)?'checked':''} onchange="audPersonToggle(${audArgs(p.id)},this.checked)"></td><td><button id="aud-person-${safe(p.id)}" class="aud-person-link" onclick="audPersonEdit(${audArgs(p.id)})">${safe(p.name||p.code)}</button>${p.name?`<small class="muted">${safe(p.code)}</small>`:''}</td><td>${safe((x.audiences||[]).find(a=>a.id===p.audienceId)?.name||'Sin audiencia')}</td><td>${audPeopleView==='adoption'?audPersonAdoptionCell(x,p,b):safe(p[audPeopleView==='position'?'position':'authority']||'Sin clasificar')}</td><td class="aud-action-cell"><button class="secondary" aria-label="Ver ficha de ${safe(p.name||p.code)}" onclick="audPersonEdit(${audArgs(p.id)})">Ver</button></td></tr>`).join('')||'<tr><td colspan="5">No hay personas en este filtro.</td></tr>'}</tbody></table></div><div class="aud-list-toolbar"><button class="secondary" ${audPeoplePage===0?'disabled':''} onclick="audPeoplePage--;audUIRender()">Anterior</button><span>${audPeoplePage+1} de ${pages}</span><button class="secondary" ${audPeoplePage>=pages-1?'disabled':''} onclick="audPeoplePage++;audUIRender()">Siguiente</button></div>${audPeopleView==='adoption'&&!b?'<p class="muted">Cada persona recibe los comportamientos de su audiencia. Abre su ficha para valorarlos o elige un comportamiento arriba para comparar sus estados.</p>':''}</details></section>${audDrawerHTML(x)}`;
}
function audSelectionTools(n){return n?`<div class="aud-selection-bar"><b id="aud-selected-count">${n}</b> seleccionadas<button class="primary" onclick="audOpenBulk()">Modificar seleccionadas</button><button class="secondary" onclick="audPersonSelection.clear();audUIRender()">Quitar selección</button></div>`:'';}
function audSelectFiltered(){audPersonRows(current()).forEach(p=>audPersonSelection.add(p.id));audUIRender();}
function audPersonToggle(id,checked){if(checked)audPersonSelection.add(id);else audPersonSelection.delete(id);const target=document.getElementById('aud-selection-tools');if(target)target.innerHTML=audSelectionTools(audPersonSelection.size);}
function audPersonEdit(id){const x=current(),p=(x.audiencePeople||[]).find(p=>p.id===id);if(!p)return;audPersonEditing=id;audDrawerMode='person';audPeopleExpanded=true;const choices=audAdoptionBehaviors(x,p);audDrawerBehaviorId=choices.some(b=>b.id===audBehaviorId)?audBehaviorId:choices[0]?.id||'';audUIRender();}
function audOpenBulk(){if(!audPersonSelection.size)return;audDrawerMode='bulk';audPersonEditing=null;const choices=audDrawerChoices(current());audDrawerBehaviorId=choices.some(b=>b.id===audBehaviorId)?audBehaviorId:choices[0]?.id||'';audUIRender();}
function audMountDrawer(){const d=typeof document!=='undefined'?document.getElementById('aud-person-drawer'):null;if(d&&!d.open){d.showModal();d.querySelector('.aud-drawer-close')?.focus();}}
function audCloseDrawer(e){e?.preventDefault();const id=audPersonEditing;document.getElementById('aud-person-drawer')?.close();audDrawerMode='';audPersonEditing=null;audUIRender();if(id)document.getElementById('aud-person-'+id)?.focus({preventScroll:true});}
function audDrawerBehaviorChange(id){audDrawerBehaviorId=id;const p=(current().audiencePeople||[]).find(p=>p.id===audPersonEditing);document.getElementById('aud-adoption-fields').innerHTML=audAdoptionForm(current(),p,audDrawerMode==='bulk');}
function audAdoptionForm(x,p,bulk){
 const b=(x.behaviors||[]).find(b=>b.id===audDrawerBehaviorId);if(!b)return '<p class="muted">No hay comportamientos aplicables. Crea uno en Diseño y asígnalo a esta audiencia.</p>';
 const latest=p?audLatestAdoption(p,b.id):null,eligible=bulk?(x.audiencePeople||[]).filter(v=>audPersonSelection.has(v.id)&&audApplicable(b,v)).length:1;
 return `<form onsubmit="audSaveAdoption(event,${bulk})"><input type="hidden" name="behaviorId" value="${safe(b.id)}">${bulk?`<p><b>${eligible}</b> personas aplicables de ${audPersonSelection.size} seleccionadas. Las demás no se modificarán.</p>`:''}${latest?`<p>Estado actual: ${audStateBadge(p,b)} · ${safe(latest.observedOn)}</p>`:''}<label>Estado observado<select name="stage" required>${Object.entries(AUD_ADOPTION_STAGES).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><details><summary>Cómo elegir el estado</summary>${Object.values(AUD_ADOPTION_STAGES).map(v=>`<p><b>${v.label}:</b> ${v.help}</p>`).join('')}</details><div class="aud-filtergrid"><label>Fecha de observación<input name="observedOn" type="date" required value="${audLocalDate()}" max="${audLocalDate()}"></label><label>Fuente<input name="source" required placeholder="Registro de uso, observación, entrevista…"></label></div><label>Qué observaste<textarea name="evidence" required placeholder="Ej. Registró 4 de las 5 solicitudes de esta semana sin ayuda."></textarea></label><label>Oportunidad de observar<select name="context">${Object.entries(AUD_ADOPTION_CONTEXTS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><details><summary>Frecuencia, autonomía y barreras</summary><div class="aud-filtergrid"><label>Oportunidades<input name="opportunities" type="number" min="0" step="1"></label><label>Ejecuciones<input name="executions" type="number" min="0" step="1"></label></div><label>Autonomía<select name="autonomy"><option value="">Sin registrar</option><option value="supported">Con apoyo</option><option value="independent">Sin ayuda</option></select></label><label>Barreras observadas<textarea name="barriers"></textarea></label></details><p class="muted">Para Realiza o Sostiene, registra autonomía sin ayuda. La categoría no se calcula a partir de NPS o posicionamiento.</p>${b.adoptionCriteria?`<p><b>Criterio de Sostiene:</b> ${safe(b.adoptionCriteria)}</p>`:'<p class="notice">Antes de usar Sostiene, define abajo el periodo y frecuencia esperados.</p>'}${bulk?'<label class="aud-check-label"><input name="bulkEvidence" type="checkbox" required> Confirmo que esta observación corresponde a cada persona aplicable seleccionada.</label>':''}<button class="primary" ${eligible?'':'disabled'}>Guardar valoración${bulk?' masiva':''}</button></form><details><summary>Definir criterio de Sostiene</summary><form onsubmit="audSaveAdoptionCriteria(event)"><input type="hidden" name="behaviorId" value="${safe(b.id)}"><label>Qué debe repetirse, con qué frecuencia y durante cuánto tiempo<textarea name="criteria" required placeholder="Ej. Registrar al menos 4 de cada 5 solicitudes durante cuatro semanas consecutivas.">${safe(b.adoptionCriteria||'')}</textarea></label><button class="secondary">Guardar criterio</button></form></details>${p?audAdoptionHistoryHTML(p,b.id):''}`;
}
function audAdoptionHistoryHTML(p,behaviorId){const rows=(p.adoptionHistory||[]).filter(r=>r.behaviorId===behaviorId).slice().sort((a,b)=>b.observedOn.localeCompare(a.observedOn)||b.recordedAt.localeCompare(a.recordedAt));return `<details><summary>Historial · ${rows.length} valoraciones</summary><div class="aud-history">${rows.map(r=>`<article><b>${safe(AUD_ADOPTION_STAGES[r.stage]?.label||r.stage)}</b> · ${safe(r.observedOn)}<p>${safe(r.evidence)}</p><small>${safe(r.source)} · ${safe(AUD_ADOPTION_CONTEXTS[r.context]||'')} · ${r.mode==='bulk'?'Valoración masiva':'Individual'}</small>${r.opportunities!==null&&r.opportunities!==undefined?`<p>${r.executions??'—'} ejecuciones / ${r.opportunities} oportunidades</p>`:''}${r.barriers?`<p>Barreras: ${safe(r.barriers)}</p>`:''}${r.criteriaSnapshot?`<p>Criterio al valorar: ${safe(r.criteriaSnapshot)}</p>`:''}</article>`).join('')||'<p>Sin valoraciones registradas.</p>'}</div></details>`;}
function audDrawerHTML(x){
 if(!audDrawerMode)return '';const bulk=audDrawerMode==='bulk',p=(x.audiencePeople||[]).find(v=>v.id===audPersonEditing);if(!bulk&&!p)return '';
 const title=bulk?`Modificar ${audPersonSelection.size} personas`:p.name||p.code;
 return `<dialog id="aud-person-drawer" class="aud-drawer" aria-labelledby="aud-drawer-title" oncancel="audCloseDrawer(event)"><header><h2 id="aud-drawer-title">${safe(title)}</h2><button type="button" class="secondary aud-drawer-close" onclick="audCloseDrawer()" aria-label="Cerrar ficha">Cerrar ×</button></header>${bulk?`<details><summary>Ver personas seleccionadas</summary><div class="aud-history">${(x.audiencePeople||[]).filter(v=>audPersonSelection.has(v.id)).map(v=>`<p>${safe(v.name||v.code)}</p>`).join('')}</div></details>`:`<p class="muted">${safe(p.code)} · ${safe((x.audiences||[]).find(a=>a.id===p.audienceId)?.name||'Sin audiencia')}</p><details><summary>Datos de la persona</summary>${[['Cargo',p.job],['Vicepresidencia',p.vicepresidency],['Dirección',p.direction],['Equipo',p.team],['Rol',p.changeRole],['Correo',p.email]].map(([n,v])=>`<p><b>${n}:</b> ${safe(v||'—')}</p>`).join('')}</details>`}<section class="aud-drawer-section"><h3>Adopción por comportamiento</h3>${!bulk?audAssignedBehaviorsHTML(x,p):''}${audBehaviorPicker(x,true,bulk?null:p)}<div id="aud-adoption-fields">${audAdoptionForm(x,p,bulk)}</div></section><details class="aud-drawer-section"><summary>Posicionamiento, incidencia y audiencia</summary><form onsubmit="audPersonSave(event,${bulk})">${audPersonFields(p||{},bulk)}<button class="primary">Guardar ${bulk?'en seleccionadas':'cambios'}</button></form></details><p id="aud-drawer-message" role="status"></p></dialog>`;
}
function audSaveAdoption(e,bulk){e.preventDefault();try{const result=audRecordAdoption(current(),bulk?new Set(audPersonSelection):new Set([audPersonEditing]),Object.fromEntries(new FormData(e.target)),bulk);save();audUIRender();const m=document.getElementById('aud-drawer-message');if(m)m.textContent=`${result.updated} persona(s) valoradas${result.skipped?'; '+result.skipped+' no aplicables, sin cambios':''}.`;}catch(err){alert(err.message);}}
function audSaveAdoptionCriteria(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),b=(current().behaviors||[]).find(b=>b.id===data.behaviorId),criteria=String(data.criteria||'').trim();if(!b||!criteria)return alert('Describe el periodo y la frecuencia para Sostiene.');b.adoptionCriteria=criteria;save();const note=document.getElementById('aud-drawer-message');if(note)note.textContent='Criterio guardado. Puedes continuar con la valoración.';}
function audPersonSave(e,bulk){e.preventDefault();const x=current(),ids=bulk?new Set(audPersonSelection):new Set([audPersonEditing]);if(!ids.size)return alert('Selecciona al menos una persona.');try{const n=audApplyPersonChanges(x,ids,Object.fromEntries(new FormData(e.target)),bulk);save();audUIRender();const m=document.getElementById('aud-drawer-message');if(m)m.textContent=`${n} persona(s) actualizadas.`;}catch(err){alert(err.message);}}
function audAdoptionDistribution(x){const b=audCurrentBehavior(x);if(!b)return `<section class="panel"><h2>Adopción por comportamiento</h2>${audBehaviorPicker(x)}${audPersonFilterHTML(x)}<p>Elige un comportamiento para comparar la adopción de las personas a quienes aplica. La asignación ya viene de su audiencia.</p></section>`;const result=audAdoptionSummary(x,b.id),eligible=result.rows.filter(p=>audApplicable(b,p));return `<section class="panel"><h2>Adopción por comportamiento</h2>${audBehaviorPicker(x)}${audPersonFilterHTML(x)}<p><b>${result.total}</b> personas aplicables · ${result.notApplicable} fuera del alcance de este comportamiento</p><div class="aud-adoption-cards">${Object.entries(AUD_ADOPTION_STAGES).map(([key,meta])=>`<button class="aud-stage-card" style="--aud-state:${meta.color}" onclick="audViewStagePeople(${audArgs(key)})"><span>${meta.label}</span><strong>${result.counts[key]}</strong><small>${result.total?(100*result.counts[key]/result.total).toLocaleString('es',{maximumFractionDigits:1}):0}% de las personas aplicables</small></button>`).join('')}</div><details><summary>Ver distribución por audiencia</summary><div class="aud-history">${[...new Set(eligible.map(p=>p.audienceId||''))].map(id=>{const group=audAdoptionSummary(x,b.id,eligible.filter(p=>(p.audienceId||'')===id));return `<article><b>${safe((x.audiences||[]).find(a=>a.id===id)?.name||'Sin audiencia')} · ${group.total} personas</b>${Object.entries(group.counts).map(([k,n])=>`<p>${AUD_ADOPTION_STAGES[k].label}: ${n}</p>`).join('')}</article>`;}).join('')||'<p>No hay personas aplicables en este filtro.</p>'}</div></details><details><summary>Criterios y acompañamiento</summary>${Object.entries(AUD_ADOPTION_STAGES).map(([k,v])=>`<p><b>${v.label}:</b> ${v.help} ${({unknown:'Recoger evidencia y revisar si hubo oportunidad.',understands:'Facilitar una primera práctica.',tries:'Dar apoyo y resolver dificultades.',performs:'Asegurar oportunidades y seguimiento.',sustains:'Mantener las condiciones y revisar retrocesos.'})[k]}</p>`).join('')}${b.adoptionCriteria?`<p><b>Para Sostiene:</b> ${safe(b.adoptionCriteria)}</p>`:''}</details></section>`;}
function audViewStagePeople(stage){audPeopleView='adoption';audPersonFilters.adoptionState=stage;audienceTab='registro';audPeopleExpanded=true;audPeoplePage=0;audPersonSelection.clear();audUIRender();}
function audienceMap(x,counts){return `<div class="flex"><button class="${audDistributionView==='adoption'?'primary':'secondary'}" onclick="audDistributionView='adoption';audUIRender()">Adopción</button><button class="${audDistributionView==='strategic'?'primary':'secondary'}" onclick="audDistributionView='strategic';audUIRender()">Mapa estratégico y estrategias</button></div>${audDistributionView==='adoption'?audAdoptionDistribution(x):audienceStrategicMap(x,counts)}`;}
